  check('structure frozen once attempts exist (delete → 409)', (await call('DELETE', `/assessments/quizzes/${Q1}/questions/${ids.tf}`, { token: tina })).status === 409);
  check('delete quiz with attempts → 409', (await call('DELETE', `/assessments/quizzes/${Q1}`, { token: tina })).status === 409);
  check('back to draft with attempts → 409', (await call('POST', `/assessments/quizzes/${Q1}/status`, { token: tina, body: { status: 'draft' } })).status === 409);

  section('Quizzes: stats and score override');
