  check('override on an in-progress attempt → 409', (await call('POST', `/assessments/quizzes/${qR.id}/attempts/${starts[0].body.id}/override`, { token: tina, body: { score: 0, note: 'x' } })).status === 409);
  check('student sees the overridden score and note', await (async () => { const r = (await call('GET', `/assessments/quizzes/${Q1}/attempts/${bDone.body.id}`, { token: bob })).body; return r.score === 6.5 && /Partial credit/.test(r.override_note); })());

  section('Quizzes: show_answers revealed only after close, only to finishers');
  const qS = (await mq({ title: 'Reveal quiz', show_answers: true, max_attempts: 2, duration_minutes: 30 })).body;
  const sa = (await addQ(qSingle, tina, qS.id)).body.id;
  await addQ(qShort, tina, qS.id);
  await call('PUT', `/assessments/quizzes/${qS.id}`, { token: tina, body: { closes_at: iso(DAY) } });
  await call('POST', `/assessments/quizzes/${qS.id}/status`, { token: tina, body: { status: 'published' } });
  const sA = (await call('POST', `/assessments/quizzes/${qS.id}/attempts`, { token: ann })).body;
  const sBt = (await call('POST', `/assessments/quizzes/${qS.id}/attempts`, { token: bob })).body;
  const sDone = await call('POST', `/assessments/quizzes/${qS.id}/attempts/${sA.id}/submit`, { token: ann, body: { responses: { [sa]: 'a' } } });
  check('show_answers on but quiz still open → nothing revealed', sDone.body.answers_visible === false && leakFree(sDone.body.questions), sDone.body.questions);
  check('student detail says answers not visible yet', (await call('GET', `/assessments/quizzes/${qS.id}`, { token: ann })).body.answers_visible === false);
  const capPut = await call('PUT', `/assessments/quizzes/${qS.id}`, { token: tina, body: { closes_at: iso(-1000) } });
  check('moving closes_at to the past caps in-progress deadlines', capPut.status === 200 && (await db.quizAttempt.findUnique({ where: { id: sBt.id } })).deadline_at <= new Date());
  const rev = await call('GET', `/assessments/quizzes/${qS.id}/attempts/${sA.id}`, { token: ann });
  check('after closes_at the finisher sees correct answers, explanation and per-question result', rev.body.answers_visible === true && rev.body.questions.find(q => q.id === sa).answer === 'b' && rev.body.questions.find(q => q.id === sa).explanation === 'Basic arithmetic' && rev.body.questions.find(q => q.id === sa).correct === false, rev.body.questions);
  const revB = await call('GET', `/assessments/quizzes/${qS.id}/attempts/${sBt.id}`, { token: bob });
  check('a student whose attempt expired unsubmitted is auto-submitted and then allowed to review', revB.body.status === 'graded' && revB.body.answers_visible === true, revB.body);
  check('student without any attempt sees no answers (no attempt id to open, detail flag false)', (await call('GET', `/assessments/quizzes/${qS.id}`, { token: eve.token })).body.answers_visible === false && leakFree((await call('GET', `/assessments/quizzes/${qS.id}`, { token: eve.token })).body));
  check('a non-roster student cannot open any attempt', (await call('GET', `/assessments/quizzes/${qS.id}/attempts/${sA.id}`, { token: cid })).status === 403);
  check('a classmate cannot read it', (await call('GET', `/assessments/quizzes/${qS.id}/attempts/${sA.id}`, { token: eve.token })).status === 404);
  const qS2 = (await mq({ title: 'Manually closed reveal', show_answers: true, max_attempts: 1 })).body;
  await addQ(qSingle, tina, qS2.id);
  await call('POST', `/assessments/quizzes/${qS2.id}/status`, { token: tina, body: { status: 'published' } });
  const mAt = (await call('POST', `/assessments/quizzes/${qS2.id}/attempts`, { token: ann })).body;
  await call('POST', `/assessments/quizzes/${qS2.id}/attempts/${mAt.id}/submit`, { token: ann, body: {} });
  check('status published (no closes_at): hidden', (await call('GET', `/assessments/quizzes/${qS2.id}/attempts/${mAt.id}`, { token: ann })).body.answers_visible === false);
  const mAt2 = (await call('POST', `/assessments/quizzes/${qS2.id}/attempts`, { token: eve.token })).body;
  await call('POST', `/assessments/quizzes/${qS2.id}/status`, { token: tina, body: { status: 'closed' } });
  check('closing a quiz ends in-progress attempts (auto-submitted on next access)', (await call('GET', `/assessments/quizzes/${qS2.id}/attempts/${mAt2.id}`, { token: eve.token })).body.status === 'graded');
  check('after the lecturer closes it: revealed', (await call('GET', `/assessments/quizzes/${qS2.id}/attempts/${mAt.id}`, { token: ann })).body.answers_visible === true);
  check('show_answers off: never revealed even when closed', await (async () => { await db.quiz.update({ where: { id: Q1 }, data: { status: 'closed', closes_at: new Date(Date.now() - 1000) } }); const r = await call('GET', `/assessments/quizzes/${Q1}/attempts/${AT.id}`, { token: ann }); return r.body.answers_visible === false && leakFree(r.body.questions); })());
  await db.quiz.update({ where: { id: Q1 }, data: { status: 'published', closes_at: null } });
  check('isolation: school B cannot read school A quiz', (await call('GET', `/assessments/quizzes/${Q1}`, { token: B.admin })).status === 404);
  check('isolation: school B student cannot open school A attempt', (await call('GET', `/assessments/quizzes/${Q1}/attempts/${AT.id}`, { token: B.ann })).status === 404);
  check('isolation: B stats → 404', (await call('GET', `/assessments/quizzes/${Q1}/stats`, { token: B.admin })).status === 404);
  check('officer oversight lists quizzes by offering', (await call('GET', `/assessments/quizzes?offering_id=${o1.id}`, { token: officer })).body.length >= 6);
  check('quizzes of a lecturer are scoped to them', (await call('GET', '/assessments/quizzes', { token: tom })).body.length === 0);
  check('finance cannot list quizzes', (await call('GET', '/assessments/quizzes', { token: finance })).status === 403);

  // ═══ GRADEBOOK ═════════════════════════════════════════════════════════════════════
  section('Gradebook: weighted CA on graded items');
  // fresh offering with exact numbers
  const { off: og, subj: sg } = await mkOffering(S, 'Networks', 'CS301', S.teachers.tina, [S.students.ann, S.students.bob, eve.s, fay.s]);
  const mkA = async (title, max, weight) => { const a = (await mk({ offering_id: og.id, title, max_score: max, weight })).body; await call('POST', `/assessments/assignments/${a.id}/status`, { token: tina, body: { status: 'published' } }); return a; };
  const g1a = await mkA('Lab 1', 20, 1), g2a = await mkA('Lab 2', 10, 3);
  const draftA = (await mk({ offering_id: og.id, title: 'Hidden draft', weight: 50 })).body;
  const submitFor = async (a, st, text) => (await call('POST', `/assessments/assignments/${a.id}/submit`, { token: st, body: { text } })).body;
  const gradeFor = async (a, sid, score) => call('POST', `/assessments/assignments/${a.id}/submissions/${sid}/grade`, { token: tina, body: { score } });
  const sAnn1 = await submitFor(g1a, ann, 'l1'), sAnn2 = await submitFor(g2a, ann, 'l2'), sBob1 = await submitFor(g1a, bob, 'l1');
  await gradeFor(g1a, sAnn1.id, 15); await gradeFor(g2a, sAnn2.id, 10);
  const qG = (await mq({ offering_id: og.id, title: 'Quiz G', weight: 2, max_attempts: 2 })).body;
  await addQ({ ...qSingle, points: 1 }, tina, qG.id); await addQ({ ...qTF, points: 1 }, tina, qG.id);
  await call('POST', `/assessments/quizzes/${qG.id}/status`, { token: tina, body: { status: 'published' } });
  const gq = (await call('GET', `/assessments/quizzes/${qG.id}`, { token: tina })).body.questions;
  const aq1 = (await call('POST', `/assessments/quizzes/${qG.id}/attempts`, { token: ann })).body;
  await call('POST', `/assessments/quizzes/${qG.id}/attempts/${aq1.id}/submit`, { token: ann, body: { responses: { [gq[0].id]: 'b', [gq[1].id]: true } } });   // 1/2 = 50 %
  const aq2 = (await call('POST', `/assessments/quizzes/${qG.id}/attempts`, { token: ann })).body;
  await call('POST', `/assessments/quizzes/${qG.id}/attempts/${aq2.id}/submit`, { token: ann, body: { responses: { [gq[0].id]: 'a', [gq[1].id]: true } } });   // 0/2: the BEST attempt counts
  const gb = await call('GET', `/assessments/gradebook/${og.id}`, { token: tina });
  const annL = gb.body.students.find(s => s.name.startsWith('Ann')), bobL = gb.body.students.find(s => s.name.startsWith('Bob')), eveL = gb.body.students.find(s => s.name.startsWith('Eve'));
  check('gradebook columns: published items only (draft excluded)', gb.status === 200 && gb.body.columns.length === 3 && !gb.body.columns.some(c => c.title === 'Hidden draft'), gb.body.columns);
  check('percentages per item', annL.items[`a:${g1a.id}`].pct === 75 && annL.items[`a:${g2a.id}`].pct === 100 && annL.items[`q:${qG.id}`].pct === 50, annL.items);
  check('best quiz attempt counts', annL.items[`q:${qG.id}`].score === 1);
  check('CA = (75×1 + 100×3 + 50×2) / 6 = 79.17', annL.ca.value === 79.17 && annL.ca.counted === 3 && annL.ca.missing === 0, annL.ca);
  check('submitted-not-graded is pending, not zero; CA null when nothing graded', bobL.items[`a:${g1a.id}`].state === 'pending' && bobL.ca.value === null && bobL.ca.pending === 1 && bobL.ca.missing === 2, bobL.ca);
  check('student with no submission: all missing, CA null', eveL.ca.value === null && eveL.ca.missing === 3);
  await gradeFor(g1a, sBob1.id, 10);
  const bobL2 = (await call('GET', `/assessments/gradebook/${og.id}`, { token: tina })).body.students.find(s => s.name.startsWith('Bob'));
  check('only graded items count: Bob CA = 50 from one item, 2 missing reported', bobL2.ca.value === 50 && bobL2.ca.counted === 1 && bobL2.ca.missing === 2, bobL2.ca);
  check('officer reads any gradebook', (await call('GET', `/assessments/gradebook/${og.id}`, { token: officer })).status === 200);
  check('admin reads any gradebook', (await call('GET', `/assessments/gradebook/${og.id}`, { token: admin })).status === 200);
  check('other lecturer cannot read', (await call('GET', `/assessments/gradebook/${og.id}`, { token: tom })).status === 403);
  check('finance cannot read', (await call('GET', `/assessments/gradebook/${og.id}`, { token: finance })).status === 403);
  check('non-roster student cannot read', (await call('GET', `/assessments/gradebook/${og.id}`, { token: cid })).status === 403);
  const sg1 = await call('GET', `/assessments/gradebook/${og.id}`, { token: ann });
  check('student gets only their own line via the offering endpoint', sg1.status === 200 && sg1.body.students.length === 1 && sg1.body.students[0].name.startsWith('Ann'), sg1.body.students?.map(s => s.name));
  const me = await call('GET', '/assessments/gradebook/me', { token: ann });
  check('student /me: own lines per offering', me.status === 200 && me.body.some(x => x.offering.id === og.id && x.line.ca.value === 79.17) && me.body.every(x => x.line.name.startsWith('Ann')), me.body);
  check('/me for a staff user → 403', (await call('GET', '/assessments/gradebook/me', { token: tina })).status === 403);
  check('/me hides classmates', !JSON.stringify(me.body).includes('Bob'));
  check('unknown offering → 404', (await call('GET', '/assessments/gradebook/nope', { token: tina })).status === 404);
  check('isolation: school B cannot read the gradebook', (await call('GET', `/assessments/gradebook/${og.id}`, { token: B.admin })).status === 404);

  section('Gradebook: export CA as DRAFT marks');
  const mkMark = (st, status, extra = {}) => db.mark.create({ data: { id: uuid(), student_id: st.id, subject_id: sg.id, term_id: S.t1.id, student_name: st.first_name, subject_name: sg.name, ca_score: 11, exam_score: 55, total_score: 0, status, offering_id: og.id, ...extra } });
  const sFay = await submitFor(g2a, fay.token, 'f'); await gradeFor(g2a, sFay.id, 5);   // Fay: graded work but a PUBLISHED mark
