  check('default (no dry_run flag) is a SAFE preview', (await exp({ token: tina, body: {} })).body.dry_run === true);
  check('preview wrote nothing', (await db.mark.count({ where: { subject_id: sg.id, student_id: S.students.ann.id } })) === 0);
  check('officer may preview', (await exp({ token: officer, body: { dry_run: true } })).status === 200);
